const Template: ComponentStory<typeof Root> = (args) => (
  <div style={{ height: 400 }}>
    <Root {...args} />
  </div>
);

export const defaultSearchField = Template.bind({});

export const withOnClearFunction = Template.bind({});
withOnClearFunction.args = {
  onClear: () => alert('Cleared the input!'),
};

export const Disabled = Template.bind({});
Disabled.args = {
  placeholder: 'Search',
  size: 'large',
  disabled: true,
  children: (
    <SearchField.Filter placeholder="Filter">
      <SearchField.FilterOption value="first-option">First Option</SearchField.FilterOption>
      <SearchField.FilterOption value="second-option">Second Option</SearchField.FilterOption>
      <SearchField.FilterOption value="third-option">Third Option</SearchField.FilterOption>
      <SearchField.FilterOption value="fourth-option">Fourth Option</SearchField.FilterOption>
    </SearchField.Filter>
  ),
};

export const WithFilter = (): JSX.Element => {
  const [value, setValue] = useState('');
  const [filterValue, setFilterValue] = useState();

  const handleChange = (e: FormEvent<HTMLInputElement>) => {
    console.log(e.currentTarget.value);
    setValue(e.currentTarget.value);
  };

  const onSearch = (v: string) => {
    alert(`searching for ${filterValue}+${v}`);
  };

  const onClear = () => {
    setValue('');
  };

  return (
    <div style={{ height: 300 }}>
      <Root
        placeholder="Search"
        value={value}
        size="large"
        onChange={handleChange}
        onClear={onClear}
        onSearch={onSearch}
      >
        <Filter placeholder="Filter" value={filterValue} onChange={(v) => setFilterValue(v)}>
          <FilterOption value="first-option">First Option</FilterOption>
          <FilterOption value="second-option">Second Option</FilterOption>
          <FilterOption value="third-option">Third Option</FilterOption>
          <FilterOption value="fourth-option">Fourth Option</FilterOption>
        </Filter>
      </Root>
    </div>
  );
};

export const Controlled = (): JSX.Element => {
  const [value, setValue] = useState('');

  const handleChange = (e: FormEvent<HTMLInputElement>) => {
    console.log(e.currentTarget.value);
    setValue(e.currentTarget.value);
  };

  const onSearch = (v: string, e: React.KeyboardEvent<HTMLInputElement>) => {
    alert(`searching for ${v}`);
    console.log(e);
  };

  const onClear = () => {
    setValue('');
  };

  return (
    <div style={{ height: 200 }}>
      <SearchField.Root
        placeholder="Search"
        value={value}
        size="large"
        onChange={handleChange}
        onClear={onClear}
        onSearch={onSearch}
      />
    </div>
  );
};
